DROP TABLE IF EXISTS `wowlheim_tool`;
CREATE TABLE `wowlheim_tool` (`item_id` INT UNSIGNED NOT NULL PRIMARY KEY, `kind` VARCHAR(8) NOT NULL COMMENT 'axe | pick', `tier` TINYINT UNSIGNED NOT NULL DEFAULT 1, `damage` FLOAT NOT NULL DEFAULT 0 COMMENT 'Valheim m_damages.m_chop (hache) / m_pickaxe (pic)') ENGINE=InnoDB DEFAULT CHARSET=utf8;
ALTER TABLE `wowlheim_recipe` MODIFY `station` VARCHAR(16) NOT NULL DEFAULT '' COMMENT 'vide = sans station (Valheim : fabrication a la main)';
DELETE FROM `wowlheim_recipe_ingredient`; DELETE FROM `wowlheim_recipe`;
DROP TABLE IF EXISTS `wowlheim_smelter`;
CREATE TABLE `wowlheim_smelter` (`kind` VARCHAR(16) NOT NULL PRIMARY KEY COMMENT 'wowlheim_piece_template.kind', `name` VARCHAR(64) NOT NULL, `fuel_item` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'm_fuelItem', `max_ore` INT UNSIGNED NOT NULL COMMENT 'm_maxOre', `max_fuel` INT UNSIGNED NOT NULL COMMENT 'm_maxFuel', `fuel_per_product` INT UNSIGNED NOT NULL COMMENT 'm_fuelPerProduct', `sec_per_product` FLOAT NOT NULL COMMENT 'm_secPerProduct', `requires_roof` TINYINT UNSIGNED NOT NULL COMMENT 'm_requiresRoof', `spawn_stack` TINYINT UNSIGNED NOT NULL COMMENT 'm_spawnStack', `smoke_x` FLOAT NOT NULL, `smoke_y` FLOAT NOT NULL, `smoke_z` FLOAT NOT NULL, `smoke_radius` FLOAT NOT NULL COMMENT 'SmokeSpawner.m_testRadius') ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='composant Smelter de Valheim';
DROP TABLE IF EXISTS `wowlheim_smelter_conversion`;
CREATE TABLE `wowlheim_smelter_conversion` (`kind` VARCHAR(16) NOT NULL, `idx` TINYINT UNSIGNED NOT NULL, `from_item` INT UNSIGNED NOT NULL, `to_item` INT UNSIGNED NOT NULL, PRIMARY KEY (`kind`,`idx`)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Smelter.m_conversion (ordre de Valheim)';
DROP TABLE IF EXISTS `wowlheim_piece_use`;
CREATE TABLE `wowlheim_piece_use` (`piece_id` INT UNSIGNED NOT NULL PRIMARY KEY COMMENT 'wowlheim_piece_template.id', `kind` VARCHAR(16) NOT NULL COMMENT 'container | door | bed', `name` VARCHAR(64) NOT NULL COMMENT 'm_name traduit', `width` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Container.m_width', `height` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Container.m_height', `privacy` TINYINT UNSIGNED NOT NULL DEFAULT 2 COMMENT 'Container.m_privacy : 0 Private, 1 Group, 2 Public', `check_guard` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'm_checkGuardStone', `can_not_be_closed` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Door.m_canNotBeClosed', `key_item` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Door.m_keyItem', `consume_key` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Door.m_consumeKey') ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='composants Container / Door / Bed de Valheim';
DROP TABLE IF EXISTS `wowlheim_tree`;
CREATE TABLE `wowlheim_tree` (`entry` INT UNSIGNED NOT NULL PRIMARY KEY, `kind` VARCHAR(8) NOT NULL, `min_tier` TINYINT UNSIGNED NOT NULL DEFAULT 0, `next_entry` INT UNSIGNED NOT NULL DEFAULT 0, `next_count` TINYINT UNSIGNED NOT NULL DEFAULT 0, `next_spacing` FLOAT NOT NULL DEFAULT 0, `next_distance` FLOAT NOT NULL DEFAULT 0, `stump_go` INT UNSIGNED NOT NULL DEFAULT 0, `stump_seconds` INT UNSIGNED NOT NULL DEFAULT 0, `drop_item` INT UNSIGNED NOT NULL DEFAULT 0, `drop_min` INT UNSIGNED NOT NULL DEFAULT 0, `drop_max` INT UNSIGNED NOT NULL DEFAULT 0, `drop_chance` FLOAT NOT NULL DEFAULT 0, `tool` VARCHAR(8) NOT NULL DEFAULT 'axe', `rolls_min` INT UNSIGNED NOT NULL DEFAULT 0, `rolls_max` INT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='TreeBase/TreeLog/MineRock/Destructible de Valheim';
DROP TABLE IF EXISTS `wowlheim_tree_drop`;
CREATE TABLE `wowlheim_tree_drop` (`entry` INT UNSIGNED NOT NULL, `item` INT UNSIGNED NOT NULL, `weight` FLOAT NOT NULL, `stack_min` INT UNSIGNED NOT NULL, `stack_max` INT UNSIGNED NOT NULL, PRIMARY KEY (`entry`,`item`)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='DropTable de Valheim (m_drops)';
